// gmm_clasificar.h  |  Jackson Five · NASA Space Apps 2026
// GMM inference (TinyML) and the 7-day Markov forecast for the ESP32.
//
// Kept in its own file so the exact same math can also be tested on a computer.
// No libraries needed: only multiplications and one exponential per group.
// The model parameters live in gmm_modelo.h (generated by entrenar_gmm.py).
#pragma once
#include <math.h>
#include "gmm_modelo.h"

// Classifies one reading with the Gaussian Mixture Model.
//   temperatura   air temperature (°C)
//   humedad       relative air humidity (%)
//   probabilidad  output: how likely each group is (0 to 1, they add up to 1)
// Returns the index of the most likely group (see GMM_NOMBRE in gmm_modelo.h).
//
// Math, per group g:
//   score[g] = log(weight) - 0.5*log(det(cov)) - log(2*pi)  - 0.5 * Mahalanobis distance
//            = GMM_CONSTANTE[g]                               - 0.5 * d' * inv(cov) * d
// then a softmax turns the scores into probabilities.
inline int gmm_clasificar(float temperatura, float humedad, float probabilidad[GMM_N_GRUPOS]) {
  float puntaje[GMM_N_GRUPOS];   // log-score of each group
  float mejor = -1e30f;          // best score so far
  int ganador = 0;               // index of the best group

  for (int g = 0; g < GMM_N_GRUPOS; g++) {
    // How far is the reading from the center of the group?
    float d0 = temperatura - GMM_CENTRO[g][0];
    float d1 = humedad - GMM_CENTRO[g][1];
    // "Hill-shaped" distance (Mahalanobis): [d0 d1] * inverse covariance * [d0 d1]
    // The 2x2 symmetric inverse is stored as {a, b, c} = [[a, b], [b, c]].
    float a = GMM_INV_COV[g][0], b = GMM_INV_COV[g][1], c = GMM_INV_COV[g][2];
    float distancia = a * d0 * d0 + 2.0f * b * d0 * d1 + c * d1 * d1;
    // The closer to the center, the higher the score
    puntaje[g] = GMM_CONSTANTE[g] - 0.5f * distancia;
    if (puntaje[g] > mejor) { mejor = puntaje[g]; ganador = g; }
  }

  // Turn scores into probabilities that add up to 1 (softmax).
  // Subtracting the best score first avoids overflow/underflow in expf().
  float suma = 0.0f;
  for (int g = 0; g < GMM_N_GRUPOS; g++) {
    probabilidad[g] = expf(puntaje[g] - mejor);
    suma += probabilidad[g];
  }
  for (int g = 0; g < GMM_N_GRUPOS; g++) probabilidad[g] /= suma;

  return ganador;
}

// MARKOV CHAIN: forecast GMM_DIAS_PRONOSTICO days ahead.
//   prob_hoy    how likely each group is TODAY (output of gmm_clasificar)
//   pronostico  output: how likely each group is IN 7 DAYS
// Math: forecast[later] = sum over i of ( prob_today[i] x MARKOV[i][later] )
// So if the GMM is undecided today, the forecast reflects that uncertainty too.
inline void markov_pronostico(const float prob_hoy[GMM_N_GRUPOS], float pronostico[GMM_N_GRUPOS]) {
  for (int despues = 0; despues < GMM_N_GRUPOS; despues++) {     // despues = group in 7 days
    pronostico[despues] = 0.0f;
    for (int hoy = 0; hoy < GMM_N_GRUPOS; hoy++) {               // hoy = group today
      pronostico[despues] += prob_hoy[hoy] * GMM_MARKOV[hoy][despues];
    }
  }
}
